  `task_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务 key 唯一标识',
  `type` smallint NOT NULL COMMENT '审批类型 0，评论 1，提交 2，抄送 3，办理 4，驳回 5，认领 6，转办 7，委派 8，跳转 9，拿回 10，唤醒 11，前加签 12，并加签 13，后加签 14，减签 15，撤销 16，终止 17，超时',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '操作 json 内容',
  `attachments` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '附件 json 内容',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='流程审批记录';

-- ----------------------------
-- Records of flw_process_approval
