  KEY `idx_group` (`group_id`,`tenant_id`) COMMENT '群组索引',
  KEY `idx_parent` (`parent_id`) COMMENT '父文件夹索引',
  KEY `idx_tenant` (`tenant_id`) COMMENT '租户索引'
